// Afficher les résultats des tests MCP
const results = [];

// Résultat de l'initialisation
if ($input.first().json.result) {
  results.push({
    test: 'Initialisation MCP',
    status: '✅ SUCCÈS',
    server: $input.first().json.result.serverInfo.name,
    version: $input.first().json.result.serverInfo.version
  });
} else {
  results.push({
    test: 'Initialisation MCP',
    status: '❌ ÉCHEC',
    error: 'Pas de réponse valide'
  });
}

// Résultat de la liste des outils
if ($input.all()[1]?.json?.result?.tools) {
  results.push({
    test: 'Liste des outils',
    status: '✅ SUCCÈS',
    count: $input.all()[1].json.result.tools.length,
    tools: $input.all()[1].json.result.tools.slice(0, 5).map(t => t.name)
  });
} else {
  results.push({
    test: 'Liste des outils',
    status: '❌ ÉCHEC',
    error: 'Pas d\'outils trouvés'
  });
}

// Résultat du test ping
if ($input.all()[2]?.json?.result?.content) {
  results.push({
    test: 'Test Ping',
    status: '✅ SUCCÈS',
    response: $input.all()[2].json.result.content[0].text
  });
} else {
  results.push({
    test: 'Test Ping',
    status: '❌ ÉCHEC',
    error: 'Pas de réponse ping'
  });
}

return results.map(r => ({ json: r }));
